    int pos = i;
    try {
        if (!bb.hasRemaining()) {
            return pos;
        }
        int b1 = bb.get() & 0xFF;
        pos++;
        if ((b1 & 0x80) == 0) {
            sb.append((char)b1);
        } else if ((b1 & 0xE0) == 0xC0) {
            int b2 = bb.get() & 0xFF;
            pos++;
            int code = ((b1 & 0x1F) << 6) | (b2 & 0x3F);
            sb.append((char)code);
        } else if ((b1 & 0xF0) == 0xE0) {
            int b2 = bb.get() & 0xFF;
            pos++;
            int b3 = bb.get() & 0xFF;
            pos++;
            int code = ((b1 & 0x0F) << 12) | ((b2 & 0x3F) << 6) | (b3 & 0x3F);
            sb.append((char)code);
        } else if ((b1 & 0xF8) == 0xF0) {
            int b2 = bb.get() & 0xFF;
            pos++;
            int b3 = bb.get() & 0xFF;
            pos++;
            int b4 = bb.get() & 0xFF;
            pos++;
            int code = ((b1 & 0x07) << 18) | ((b2 & 0x3F) << 12) | ((b3 & 0x3F) << 6) | (b4 & 0x3F);
            sb.append(Character.highSurrogate(code));
            sb.append(Character.lowSurrogate(code));
